var import_obsidian14 = require("obsidian");

// src/view.ts
var import_obsidian12 = require("obsidian");

// src/calculator.ts
var import_obsidian2 = require("obsidian");

// src/panels.ts
function makeDraggable(panel, handle, container, storageKey) {
  handle.addClass("notelens-draggable");
  const applyPosition = (left, top) => {
    const maxLeft = Math.max(0, container.clientWidth - panel.offsetWidth);
    const maxTop = Math.max(0, container.clientHeight - panel.offsetHeight);
    panel.style.right = "auto";
    panel.style.bottom = "auto";
    panel.style.left = `${Math.min(Math.max(0, left), maxLeft)}px`;
    panel.style.top = `${Math.min(Math.max(0, top), maxTop)}px`;
  };
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) ?? "null");
    if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) requestAnimationFrame(() => applyPosition(saved.x, saved.y));
  } catch {
  }
  handle.addEventListener("pointerdown", (e3) => {
    if (e3.target.closest("button, input, select, textarea")) return;
    e3.preventDefault();
    const startX = e3.clientX;
    const startY = e3.clientY;
    const rect = panel.getBoundingClientRect();
    const parent = container.getBoundingClientRect();
    const originLeft = rect.left - parent.left;
    const originTop = rect.top - parent.top;
    panel.addClass("is-dragging");
    const onMove = (ev) => applyPosition(originLeft + ev.clientX - startX, originTop + ev.clientY - startY);
    const onUp = () => {
      window.removeEventListener("pointermove", onMove, { capture: true });
      window.removeEventListener("pointerup", onUp, { capture: true });
      panel.removeClass("is-dragging");
      try {
        localStorage.setItem(storageKey, JSON.stringify({ x: parseFloat(panel.style.left), y: parseFloat(panel.style.top) }));
      } catch {
      }
    };
    window.addEventListener("pointermove", onMove, { capture: true });
    window.addEventListener("pointerup", onUp, { capture: true });
  });
}
function shieldPanel(panel) {
  for (const type of ["pointerdown", "pointerup", "dblclick"]) panel.addEventListener(type, (e3) => e3.stopPropagation());
  panel.addEventListener("wheel", (e3) => e3.stopPropagation(), { passive: true });
  panel.addEventListener("keydown", (e3) => e3.stopPropagation());
}

